tasks.command:
$listeners=Get-NetTCPConnection -LocalPort 3033 -State Listen -ErrorAction SilentlyContinue
foreach ($listener in $listeners) {
$process=Get-CimInstance Win32_Process | Where-Object { $_.ProcessId -eq $listener.OwningProcess }
if ($process.CommandLine -notlike '*backend/dist/server.js*') {throw 'Port 3033 is used by another process'}
Stop-Process -Id $listener.OwningProcess
}
$env:PATH='C:\Users\Oli\AppData\Local\Programs\nodejs-26.13.0;' + $env:PATH
$env:PORT='3033'
$env:HOST='127.0.0.1'
$env:APP_PASSWORD='LocalTourPreview123!'
$env:DATA_DIR=Join-Path $env:TEMP 'immich-gpx-mapper-multitour-preview'
$env:STATIC_DIR=Join-Path $PWD 'frontend/build'
& 'C:\Users\Oli\AppData\Local\Programs\nodejs-26.13.0\node.exe' backend/dist/server.js
